// Binary plist encoding/decoding and RTI text input payload tests.
// Reference bytes are generated by Python plistlib (matching pyatv) to verify decoding
// correctness; the encoding side is validated by round-tripping through decoding.

import Foundation
import AppleTVControl

func runBinaryPlistTests() {
    runSuite("BinaryPlist decode _tiD") {
        // _tiD generated by fake_device.rti_encoded_data (sessionUUID=0x00..0x0F, text="hello").
        let tiData = Data(hex: "")!

        let props = RTITextInput.readArchiveProperties(tiData, paths: [
            ["sessionUUID"],
            ["documentState", "docSt", "contextBeforeInput"],
        ])

        let expectedUUID = Data((0..<16).map { UInt8($0) })
        expectEqual(props.count, 2, "parsed path count")
        expectEqual(props[0] as? Data, expectedUUID, "sessionUUID")
        expectEqual(props[1] as? String, "hello", "current text")
    }

    runSuite("RTI input payload round-trip") {
        let uuid = Data((0..<16).map { UInt8($0) })
        let payload = RTITextInput.inputTextPayload(sessionUUID: uuid, text: "café")

        let props = RTITextInput.readArchiveProperties(payload, paths: [
            ["textOperations", "targetSessionUUID", "NS.uuidbytes"],
            ["textOperations", "keyboardOutput", "insertionText"],
        ])

        expectEqual(props[0] as? Data, uuid, "sessionUUID")
        expectEqual(props[1] as? String, "café", "inserted text (non-ASCII)")
    }

    runSuite("RTI clear payload round-trip") {
        let uuid = Data((0..<16).map { UInt8($0) })
        let payload = RTITextInput.clearTextPayload(sessionUUID: uuid)

        let props = RTITextInput.readArchiveProperties(payload, paths: [
            ["textOperations", "targetSessionUUID", "NS.uuidbytes"],
            ["textOperations", "textToAssert"],
        ])

        expectEqual(props[0] as? Data, uuid, "sessionUUID")
        expectEqual(props[1] as? String, "", "textToAssert is empty")
    }
}
